-- Spanish 1 final module. Run seed_span_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'spanish-1';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: My Spanish Portfolio and Reflection$j$, $j${"prompt": "Create a Spanish portfolio and reflection of at least 700 words in total, written in English and Spanish. Write the Spanish yourself. You may use a dictionary or your lesson notes, but do not copy a full translation from a translation tool. Do not include your home address, phone number, passwords or other private details, and have a parent, guardian or teacher review your portfolio before you submit it. Proverbs 4:7 says, Wisdom is the principal thing; therefore get wisdom: and with all thy getting get understanding.\n\nPart 1: Self Introduction. Write a paragraph in Spanish of at least eight sentences that gives your name, age, where you are from, your family, your school, your hobbies and what you like to eat.\nPart 2: Conversation. Write a dialogue in Spanish of at least ten lines between two people who meet at a church event or restaurant, using greetings, questions with ¿, a request, a price or a direction, and a farewell.\nPart 3: Grammar Showcase. Show correct conjugations of ser, estar, tener, ir, one regular ar verb, one regular er verb and one regular ir verb in the present tense, and one stem changing verb. Write one sentence for each.\nPart 4: Past and Future. Write four sentences in Spanish about what you did last weekend using the preterite, and four sentences about your plans using ir a, pensar or querer.\nPart 5: Culture Report. Write at least 120 words in English about one Spanish speaking country or Hispanic community in Florida, including its history, foods, music or traditions, with at least six Spanish words.\nPart 6: Service Plan. Describe three ways you can use Spanish to serve others honestly and respectfully, including when to ask a trained interpreter for help.\nPart 7: Self Assessment. Explain what you learned, what was hardest, what you will practice and your goal for Spanish 2.\nPart 8: Faith and Reflection. Apply at least three Scripture passages from the King James Version, such as Genesis 11:9, Acts 2:6, Revelation 7:9 or Matthew 28:19, to the study of language and the call to serve people of every nation.", "rubric": "100 points. Part 1, self introduction: 15 points. Part 2, conversation: 15 points. Part 3, grammar showcase: 20 points. Part 4, past and future: 15 points. Part 5, culture report: 10 points. Part 6, service plan: 10 points. Part 7, self assessment: 5 points. Part 8, faith and reflection: 5 points. Accuracy of spelling, accents and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: My Spanish Portfolio and Reflection$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: Spanish 1$j$, $j${"questions": [{"q": "How many letters are in the Spanish alphabet?", "options": ["29", "26", "30", "27"]}, {"q": "The letter h in Spanish is:", "options": ["Like k", "Rolled", "Silent", "Like s"]}, {"q": "Buenas noches is used:", "options": ["To say thank you", "In the morning", "At noon only", "In the evening or at night"]}, {"q": "Soy de Cuba means:", "options": ["I go to Cuba", "I have Cuba", "I am from Cuba", "I like Cuba"]}, {"q": "Treinta y cinco is:", "options": ["53", "15", "35", "30"]}, {"q": "The article for the noun mesa is:", "options": ["La", "El", "Un", "Los"]}, {"q": "Las chicas altas means:", "options": ["A tall girl", "The short girls", "The tall boys", "The tall girls"]}, {"q": "Mi madre ___ en la iglesia.", "options": ["está", "tiene", "es", "hace"]}, {"q": "The yo form of hablar is:", "options": ["Hablas", "Hablo", "Hablan", "Habla"]}, {"q": "Son las tres y media means:", "options": ["It is 3:45", "It is 3:15", "It is 2:30", "It is 3:30"]}, {"q": "Me gustan las frutas means:", "options": ["I eat fruit", "I have fruit", "I buy fruit", "I like fruits"]}, {"q": "The yo form of querer is:", "options": ["Quiere", "Queremos", "Quiero", "Quero"]}, {"q": "Vamos al parque means:", "options": ["I am going to the park", "We are going to the park", "They go home", "We have a park"]}, {"q": "Ayer comí arroz means:", "options": ["Tomorrow I will eat rice", "Yesterday I ate rice", "I like rice", "I eat rice daily"]}, {"q": "Revelation 7:9 describes people of all nations, and kindreds, and people, and tongues. This teaches us to:", "options": ["Ignore strangers", "Avoid other cultures", "Speak only one language", "Love and serve people of every language"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Spanish 1$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,3,2,2,0,3,0,1,3,3,2,1,1,3}'::int[], array[$j$It has the 26 English letters plus ñ.$j$,$j$The h is always silent.$j$,$j$Noche means night.$j$,$j$Soy de means I am from.$j$,$j$Treinta is 30 and cinco is 5.$j$,$j$Mesa is feminine singular.$j$,$j$Adjectives agree with the noun.$j$,$j$Location uses estar.$j$,$j$Yo takes the o ending.$j$,$j$Media means half past.$j$,$j$Gustan is plural.$j$,$j$Querer changes e to ie.$j$,$j$Vamos is the nosotros form of ir.$j$,$j$Comí is the yo preterite form of comer.$j$,$j$The gospel is for every nation and tongue.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Spanish 1$j$ on conflict (item_id) do nothing;
end
$seed$;
